INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(150, 'anniversary', 'ˌænɪˈvɜːrsəri', 'noun', '{"zh-TW":["週年紀念；週年","週年慶"],"en":["the annual date of a past event","a celebration of longevity"]}', NULL, 'company anniversary/10th anniversary', '[{"en":"We are celebrating our 20th anniversary.","zh-TW":"我們正在慶祝20週年紀念日。"}]', '{"adjective":"annual","adverb":"annually"}', NULL, 4, 150, NULL),
(151, 'announce', '/əˈnaʊns/', 'verb', '{"zh-TW":["宣布；公告","宣布；宣告","宣布"],"en":["to make a public or official statement","to make something known publicly","to make a public statement about something"]}', '{"prefix":{"text":"an-","meaning":"toward (朝向)"},"root":{"text":"nounce","meaning":"report (報告)"},"logic":"朝向報告，即「宣布」。"}', 'announce a decision/plan/merger; announce a decision / announce that; announce the results / announce a decision / officially announce', '[{"en":"The CEO announced the merger at a press conference.","zh-TW":"執行長在記者會上宣布了合併消息。"},{"en":"The results will be announced next Monday.","zh-TW":"結果將於下週一公布。"},{"en":"They announced the winner.","zh-TW":"他們宣布了獲勝者。"},{"en":"The company announced a new product.","zh-TW":"公司宣布了一款新產品。"},{"en":"The company announced record profits.","zh-TW":"公司宣布了創紀錄的利潤。"},{"en":"They will announce the winner tomorrow.","zh-TW":"他們明天將宣布得獎者。"}]', '{"noun":"announcement","noun2":"announcer"}', NULL, 3, 151, 5),
(152, 'announcement', 'əˈnaʊnsmənt', 'noun', '{"zh-TW":["公告；通知","宣布"],"en":["an official public statement","a declaration"]}', NULL, 'make an announcement/company announcement', '[{"en":"The CEO made an important announcement.","zh-TW":"執行長發布了重要公告。"}]', '{"verb":"announce","adjective":"announcing"}', NULL, 4, 152, 501),
(153, 'annual', '/ˈænjuəl/', 'adjective', '{"zh-TW":["年度的；每年的"],"en":["occurring once every year"]}', '{"root":{"text":"annu","meaning":"year (年)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與年有關的，即「年度的」。"}', 'annual report/meeting/revenue; annual report / annual meeting / annual income', '[{"en":"The annual report shows a 15% increase in profit.","zh-TW":"年度報告顯示利潤增長了15%。"},{"en":"The annual conference is held in December.","zh-TW":"年度會議在十二月舉行。"},{"en":"The company holds its annual meeting in March.","zh-TW":"公司每年三月舉行年度會議。"},{"en":"What is your annual income?","zh-TW":"你的年收入是多少？"}]', '{"adverb":"annually"}', NULL, 2, 153, 6),
(154, 'annuity', '/əˈnjuːɪti/', 'noun', '{"zh-TW":["年金"],"en":["a fixed sum paid annually as retirement or investment income"]}', NULL, 'annuity plan / purchase an annuity / annuity payment', '[{"en":"He invested in an annuity to secure retirement income.","zh-TW":"他投資年金以確保退休收入。"},{"en":"The pension scheme pays a monthly annuity after age 60.","zh-TW":"退休金計劃在60歲後每月支付年金。"}]', '{"adjective":"annuitized"}', NULL, 3, 154, NULL),
(155, 'another', '/əˈnʌðər/', 'determiner', '{"zh-TW":["另一個；再一個"],"en":["one more; a different one"]}', NULL, 'one another / another way', '[{"en":"Would you like another cup of tea?","zh-TW":"你想再來一杯茶嗎？"},{"en":"Let''s try another approach.","zh-TW":"讓我們試試另一種方法。"}]', NULL, NULL, 3, 155, NULL),
(156, 'answer', '/ˈænsər/', 'noun', '{"zh-TW":["答案；回覆","答案；回答","回答；答案；接電話"],"en":["a reply","a solution","a reply to a question","a reply; to respond to a question or call"]}', NULL, 'in answer to / answer the phone; answer the phone / in answer to; answer the phone / answer a question / in answer to', '[{"en":"Please answer my email by Friday.","zh-TW":"請在週五前回覆我的電子郵件。"},{"en":"There is no easy answer to this.","zh-TW":"這個問題沒有簡單的答案。"},{"en":"I don''t know the answer.","zh-TW":"我不知道答案。"},{"en":"Please answer the phone.","zh-TW":"請接電話。"},{"en":"Please answer my question.","zh-TW":"請回答我的問題。"},{"en":"Nobody answered the door.","zh-TW":"沒人來應門。"}]', '{"noun":"answer","verb":"answer","adjective":"answerable"}', NULL, 2, 156, NULL),
(157, 'answerable', '/ˈɑːnsərəbl/', 'adjective', '{"zh-TW":["應負責的；應解釋的"],"en":["required to account for actions or decisions to a higher authority"]}', NULL, 'answerable to the board / answerable for decisions', '[{"en":"The manager is answerable to the board for the division''s performance.","zh-TW":"管理者對部門績效向董事會負責。"},{"en":"All executives are answerable for their spending decisions.","zh-TW":"所有高管都應對其支出決策負責。"}]', NULL, NULL, 4, 157, NULL),
(158, 'antibiotic', '/ˌæntɪbaɪˈɒtɪk/', 'noun', '{"zh-TW":["抗生素"],"en":["a medicine that kills bacteria"]}', NULL, 'take an antibiotic / antibiotic resistance', '[{"en":"The doctor prescribed a course of antibiotics.","zh-TW":"醫生開了一個療程的抗生素。"},{"en":"Do not stop taking antibiotics before the course is finished.","zh-TW":"在療程結束前不要停止服用抗生素。"}]', '{"adjective":"antibiotic"}', NULL, 4, 158, NULL),
(159, 'anticipate', '/ænˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["預期；預料"],"en":["to expect or predict something"]}', '{"prefix":{"text":"anti-","meaning":"before (之前)"},"root":{"text":"cip","meaning":"take (拿)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"在之前就拿取（準備），即「預期」。"}', 'anticipate demand/problems/growth', '[{"en":"We anticipate strong demand for the new product.","zh-TW":"我們預期新產品會有強勁需求。"},{"en":"The delay was not anticipated.","zh-TW":"這個延遲是始料未及的。"}]', '{"noun":"anticipation"}', NULL, 4, 159, 502),
(160, 'anxious', '/ˈæŋkʃəs/', 'adjective', '{"zh-TW":["焦慮的；擔心的"],"en":["feeling worried or nervous"]}', '{"root":{"text":"anx","meaning":"choke/distress (窒息/痛苦)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿痛苦不安的，即「焦慮的」。"}', 'feel anxious / anxious about', '[{"en":"She felt anxious about the job interview.","zh-TW":"她對工作面試感到焦慮。"},{"en":"He was anxious to hear the results.","zh-TW":"他急切地想知道結果。"}]', '{"noun":"anxiety","adverb":"anxiously"}', NULL, 3, 160, NULL),
(161, 'anybody', '/ˈɛnibɒdi/', 'pronoun', '{"zh-TW":["任何人"],"en":["any person at all"]}', NULL, 'anybody else / not anybody', '[{"en":"Is anybody home?","zh-TW":"有人在家嗎？"},{"en":"Anybody can learn to cook.","zh-TW":"任何人都能學會做飯。"}]', NULL, NULL, 3, 161, NULL),
(162, 'anyone', '/ˈeniwʌn/', 'pronoun', '{"zh-TW":["任何人"],"en":["any person; it doesn''t matter who"]}', NULL, 'anyone else', '[{"en":"Is anyone here?","zh-TW":"有人在嗎？"},{"en":"Anyone can apply for this position.","zh-TW":"任何人都可以申請這個職位。"}]', NULL, NULL, 2, 162, NULL),
(163, 'anything', '/ˈɛniθɪŋ/', 'pronoun', '{"zh-TW":["任何事物"],"en":["any thing at all","any thing; it doesn''t matter what"]}', NULL, 'anything else / not anything; anything else / if anything', '[{"en":"Is there anything I can do?","zh-TW":"有什麼我能做的嗎？"},{"en":"She didn''t say anything.","zh-TW":"她什麼都沒說。"},{"en":"Is there anything I can help with?","zh-TW":"有什麼我可以幫忙的嗎？"},{"en":"I''ll do anything to pass the exam.","zh-TW":"我會做任何事來通過考試。"}]', NULL, NULL, 3, 163, NULL),
(164, 'anywhere', '/ˈɛniwɛr/', 'adverb', '{"zh-TW":["任何地方"],"en":["in or to any place"]}', NULL, 'anywhere else / not anywhere', '[{"en":"You can sit anywhere you like.","zh-TW":"你可以坐任何你喜歡的位置。"},{"en":"I can''t find it anywhere.","zh-TW":"我哪裡都找不到它。"}]', NULL, NULL, 3, 164, NULL),
(165, 'apart', '/əˈpɑːrt/', 'adverb', '{"zh-TW":["分開地；相隔"],"en":["separated by distance or time"]}', NULL, 'apart from / fall apart', '[{"en":"They live far apart.","zh-TW":"他們住得很遠。"},{"en":"The old building is falling apart.","zh-TW":"那棟老建築正在坍塌。"}]', NULL, NULL, 2, 165, NULL),
(166, 'apartment', '/əˈpɑːrtmənt/', 'noun', '{"zh-TW":["公寓"],"en":["a residential unit in a building","a set of rooms for living in, usually on one floor of a building"]}', NULL, 'apartment complex / rent an apartment; apartment building / studio apartment', '[{"en":"She rents an apartment near the office.","zh-TW":"她在辦公室附近租了一間公寓。"},{"en":"The apartment comes fully furnished.","zh-TW":"這間公寓有全套家具。"},{"en":"They rented a two-bedroom apartment.","zh-TW":"他們租了一間兩房公寓。"},{"en":"The apartment complex has a swimming pool.","zh-TW":"這個公寓大樓有游泳池。"}]', '{"noun":"apartment"}', NULL, 3, 166, NULL),
(167, 'aperitif', '/əˈpɛrɪtiːf/', 'noun', '{"zh-TW":["餐前酒；開胃飲料"],"en":["an alcoholic drink served before a meal"]}', NULL, 'order an aperitif / classic aperitif', '[{"en":"The waiter offered an aperitif while we looked at the menu.","zh-TW":"我們看菜單時，服務生提供了餐前酒。"},{"en":"A dry sherry is a popular aperitif in Spain.","zh-TW":"干雪利酒是西班牙受歡迎的餐前酒。"}]', NULL, NULL, 3, 167, NULL),
(168, 'API', '/ˌeɪ piː ˈaɪ/', 'noun', '{"zh-TW":["應用程式介面"],"en":["application programming interface; allows software systems to communicate"]}', NULL, 'API integration / RESTful API / open API / API documentation', '[{"en":"The API allows third-party developers to build on the platform.","zh-TW":"API允許第三方開發者在平台上構建應用程式。"},{"en":"Seamless API integration was key to the digital transformation project.","zh-TW":"無縫的API整合是數位轉型項目的關鍵。"}]', '{"full form":"application programming interface"}', NULL, 1, 168, NULL),
(169, 'apology', 'əˈpɒlədʒi', 'noun', '{"zh-TW":["道歉；歉意","辯護"],"en":["an expression of regret","a statement of being sorry"]}', NULL, 'offer an apology/formal apology', '[{"en":"Please accept our sincere apology for the delay.","zh-TW":"請接受我們對延誤的誠摯道歉。"}]', '{"verb":"apologize","adjective":"apologetic","adverb":"apologetically"}', NULL, 3, 169, NULL),
(170, 'apparent', '/əˈpærənt/', 'adjective', '{"zh-TW":["明顯的；顯然的"],"en":["clearly visible or understood; obvious"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"par","meaning":"appear (出現)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"朝向出現的，即「明顯的」。"}', 'become apparent / for no apparent reason', '[{"en":"It became apparent that the project would exceed budget.","zh-TW":"很明顯該專案將超出預算。"},{"en":"The benefits are apparent to everyone involved.","zh-TW":"好處對所有相關人員都是顯而易見的。"}]', '{"adverb":"apparently"}', NULL, 3, 170, NULL),
(171, 'appeal', '/əˈpiːl/', 'verb', '{"zh-TW":["呼籲；上訴","吸引","吸引；呼籲；上訴"],"en":["to make a serious request","to be attractive or interesting","to attract or be interesting"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"peal","meaning":"drive/push (推動)"},"logic":"朝向推動人，即「呼籲、吸引」。"}', 'appeal to / appeal a decision; appeal to / appeal a decision / sex appeal', '[{"en":"The product appeals to health-conscious consumers.","zh-TW":"該產品吸引注重健康的消費者。"},{"en":"The company plans to appeal the court''s decision.","zh-TW":"公司計劃對法院判決提出上訴。"},{"en":"The idea doesn''t appeal to me.","zh-TW":"這個想法不吸引我。"},{"en":"They appealed the court''s decision.","zh-TW":"他們對法院的判決提出上訴。"}]', '{"adjective":"appealing","noun":"appeal"}', NULL, 2, 171, 503),
(172, 'appear', '/əˈpɪər/', 'verb', '{"zh-TW":["出現；似乎","出現；似乎；看起來"],"en":["to become visible","to seem or give the impression","to become visible; to seem"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"pear","meaning":"be visible (可見)"},"logic":"朝向可見，即「出現」。"}', 'appear to be / appear on/in; appear to be / appear in; appear to be / it appears that', '[{"en":"The error appears to have been corrected.","zh-TW":"這個錯誤似乎已被更正。"},{"en":"New opportunities appear as the market evolves.","zh-TW":"隨著市場發展，新機會不斷出現。"},{"en":"Stars appear at night.","zh-TW":"星星在夜晚出現。"},{"en":"He appears to be happy.","zh-TW":"他看起來很開心。"},{"en":"A new store appeared on our street.","zh-TW":"一家新店出現在我們的街上。"},{"en":"He appears to be very busy.","zh-TW":"他看起來非常忙碌。"}]', '{"noun":"appearance","adjective":"apparent","adverb":"apparently"}', NULL, 2, 172, NULL),
(173, 'appendix', '/əˈpɛndɪks/', 'noun', '{"zh-TW":["附錄；附件"],"en":["additional material at the end of a document"]}', NULL, 'see the appendix / attached appendix', '[{"en":"Detailed financial data can be found in the appendix.","zh-TW":"詳細的財務數據可以在附錄中找到。"},{"en":"Please refer to Appendix C for the supporting documentation.","zh-TW":"請參閱附錄C獲取支持文件。"}]', '{"plural":"appendices"}', NULL, 3, 173, NULL),
(174, 'appetizer', '/ˈæpɪtaɪzər/', 'noun', '{"zh-TW":["開胃菜；前菜"],"en":["a small dish served before the main course"]}', NULL, 'order an appetizer / light appetizer', '[{"en":"We shared a few appetizers before the main course.","zh-TW":"我們在主菜前共享了幾道開胃菜。"},{"en":"The appetizer menu includes soup and salad options.","zh-TW":"開胃菜菜單包含湯品和沙拉選項。"}]', '{"adjective":"appetizing"}', NULL, 3, 174, NULL),
(175, 'apple', '/ˈæpl/', 'noun', '{"zh-TW":["蘋果"],"en":["a round fruit with red, green, or yellow skin"]}', NULL, 'apple pie / apple juice', '[{"en":"An apple a day keeps the doctor away.","zh-TW":"一天一蘋果，醫生遠離我。"},{"en":"She bought some apples at the market.","zh-TW":"她在市場買了一些蘋果。"}]', NULL, NULL, 2, 175, NULL),
(176, 'applicability', '/ˌæplɪkəˈbɪlɪti/', 'noun', '{"zh-TW":["適用性；適用範圍"],"en":["the quality of being relevant or appropriate"]}', NULL, 'applicability of a rule / wide applicability', '[{"en":"Check the applicability of the policy to your department.","zh-TW":"查看該政策對您部門的適用性。"},{"en":"The new regulation has wide applicability across industries.","zh-TW":"新法規在各行業具有廣泛的適用性。"}]', '{"adjective":"applicable","verb":"apply"}', NULL, 5, 176, NULL),
(177, 'applicable', '/əˈplɪkəbl/', 'adjective', '{"zh-TW":["適用的；可應用的"],"en":["relevant or appropriate to a situation"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠朝向應用的，即「適用的」。"}', 'applicable to / where applicable', '[{"en":"This discount is applicable to orders over $100.","zh-TW":"此折扣適用於超過100美元的訂單。"},{"en":"Please fill in all applicable fields on the form.","zh-TW":"請填寫表格上所有適用的欄位。"}]', '{"noun":"applicability"}', NULL, 4, 177, 264),
(178, 'applicant', '/ˈæplɪkənt/', 'noun', '{"zh-TW":["申請人；應徵者"],"en":["a person who applies for something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ant","meaning":"person who (…的人)"},"logic":"朝向應用的人，即「申請人」。"}', 'job applicant / successful applicant', '[{"en":"We received over 200 applicants for the position.","zh-TW":"我們收到了超過200位該職位的應徵者。"},{"en":"Successful applicants will be notified by email.","zh-TW":"錄取者將以電子郵件通知。"}]', '{"noun":"application","verb":"apply"}', NULL, 3, 178, NULL),
(179, 'application', '/ˌæplɪˈkeɪʃən/', 'noun', '{"zh-TW":["應用程式；申請"],"en":["a computer program; a formal request"]}', NULL, 'mobile application / job application', '[{"en":"Download the application from the store.","zh-TW":"從商店下載這個應用程式。"},{"en":"I submitted my job application.","zh-TW":"我提交了工作申請。"}]', '{"verb":"apply","noun2":"applicant"}', NULL, 4, 179, 7),
(180, 'apply', '/əˈplaɪ/', 'verb', '{"zh-TW":["申請；應用"],"en":["to make a formal request","to put into operation or use"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"ply","meaning":"fold (折疊/靠近)"},"logic":"朝向靠近，即「申請、應用」。"}', 'apply for a job / apply knowledge', '[{"en":"She applied for the marketing manager position.","zh-TW":"她應徵了行銷經理職位。"},{"en":"Students learn how to apply theory to practice.","zh-TW":"學生學習如何將理論應用於實踐。"}]', '{"noun":"application","adjective":"applicable"}', NULL, 2, 180, NULL),
(181, 'appoint', '/əˈpɔɪnt/', 'verb', '{"zh-TW":["任命；指定"],"en":["to officially choose someone for a position"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"point","meaning":"point (指)"},"logic":"朝向指定某人，即「任命」。"}', 'appoint a director/representative', '[{"en":"The board appointed a new chief financial officer.","zh-TW":"董事會任命了新的財務長。"},{"en":"She was appointed to lead the project team.","zh-TW":"她被指定領導專案團隊。"}]', '{"noun":"appointment"}', NULL, 3, 181, 8),
(182, 'appointment', '/əˈpɔɪntmənt/', 'noun', '{"zh-TW":["預約；約診"],"en":["an arrangement to meet a doctor at a set time"]}', NULL, 'make an appointment / doctor appointment', '[{"en":"I need to make an appointment with my doctor.","zh-TW":"我需要預約我的醫生。"},{"en":"Please arrive ten minutes before your appointment.","zh-TW":"請在預約時間前十分鐘到達。"}]', '{"verb":"appoint","adjective":"appointed"}', NULL, 4, 182, 504),
(183, 'apportion', '/əˈpɔːrʃən/', 'verb', '{"zh-TW":["分攤；分配"],"en":["to divide and allocate something among parties"]}', NULL, 'apportion costs / apportion responsibility / apportion blame', '[{"en":"Costs were apportioned equally between the three departments.","zh-TW":"費用在三個部門之間平均分攤。"},{"en":"Responsibility was apportioned based on each party''s contribution.","zh-TW":"責任根據各方的貢獻進行了分攤。"}]', '{"noun":"apportionment"}', NULL, 3, 183, 984),
(184, 'apportionment', '/əˈpɔːrʃənmənt/', 'noun', '{"zh-TW":["分攤；分配"],"en":["the division of something among several parties"]}', NULL, 'cost apportionment / apportionment of expenses', '[{"en":"The apportionment of shared costs was agreed between divisions.","zh-TW":"共同成本的分攤在各部門之間達成了一致。"},{"en":"An equitable apportionment method was used for overhead allocation.","zh-TW":"採用了公平的分攤方法分配間接費用。"}]', '{"verb":"apportion"}', NULL, 5, 184, NULL),
(185, 'appraisal', '/əˈpreɪzəl/', 'noun', '{"zh-TW":["績效考核；評估"],"en":["a formal assessment of an employee''s job performance"]}', NULL, 'performance appraisal / annual appraisal / appraisal interview', '[{"en":"She received positive feedback during her annual appraisal.","zh-TW":"她在年度考核中收到了正面的反饋。"},{"en":"The appraisal system was redesigned to align with company values.","zh-TW":"考核制度被重新設計以與公司價值觀保持一致。"}]', '{"verb":"appraise","noun":"appraiser"}', NULL, 3, 185, 505),
(186, 'appraise', '/əˈpreɪz/', 'verb', '{"zh-TW":["評估；鑑定"],"en":["to assess the value or quality of something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"praise","meaning":"price/value (價值)"},"logic":"朝向評定價值，即「評估」。"}', 'appraise performance/property/value', '[{"en":"The property was appraised at $1.2 million.","zh-TW":"該房產被估價為120萬美元。"},{"en":"Managers appraise staff performance annually.","zh-TW":"經理每年評估員工績效。"}]', '{"noun":"appraisal"}', NULL, 3, 186, NULL),
(187, 'appreciate', '/əˈpriːʃieɪt/', 'verb', '{"zh-TW":["【主要意義-動詞】感激；欣賞","【次要意義-動詞】理解；意識到（某事的重要性/困難）","【次要意義-動詞】（資產）升值；增值"],"en":["[primary] to recognize and enjoy the value of something; to be grateful","[secondary] to fully understand a situation or problem","[secondary] to increase in value over time"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"preci","meaning":"price/value (價值)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"朝向認識價值，即「感謝、增值」。"}', 'appreciate the difficulty / appreciate your support / property appreciates', '[{"en":"I appreciate the difficulty of implementing these changes within one week.","zh-TW":"我理解在一周內實施這些變更的難度。"},{"en":"Real estate in the area has appreciated significantly over the past decade.","zh-TW":"該地區的房地產在過去十年中大幅升值。"},{"en":"We appreciate your patience while we resolve the technical issues.","zh-TW":"我們感謝您在我們解決技術問題期間的耐心等待。"}]', '{"noun":"appreciation","adjective":"appreciative"}', 'appreciate 的次要意義：「理解/意識到」（appreciate the complexity = 理解複雜性）和「升值」（assets appreciate），在 TOEIC 財務和商業文章中常見，考生常誤以為只有「感激/欣賞」的意思。', 4, 187, 265),
(188, 'appreciation', '/əˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["感謝；升值；欣賞"],"en":["gratitude; or an increase in value"]}', NULL, 'express appreciation / currency appreciation', '[{"en":"We wish to express our appreciation for your support.","zh-TW":"我們謹向您的支持表示感謝。"},{"en":"The appreciation of the property value doubled their investment.","zh-TW":"房產增值使他們的投資翻了一倍。"}]', '{"verb":"appreciate","adjective":"appreciated"}', NULL, 4, 188, NULL),
(189, 'approach', '/əˈprəʊtʃ/', 'noun', '{"zh-TW":["方法；途徑","接近"],"en":["a way of dealing with something","the act of coming near"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proach","meaning":"near (靠近)"},"logic":"朝向靠近，即「接近、方法」。"}', 'approach to / new approach', '[{"en":"We need a fresh approach to this problem.","zh-TW":"我們需要一個解決此問題的新方法。"},{"en":"The deadline is approaching rapidly.","zh-TW":"截止日期正在迅速逼近。"}]', '{"adjective":"approachable"}', NULL, 3, 189, NULL),
(190, 'appropriate', '/əˈprəʊpriət/', 'adjective', '{"zh-TW":["適當的；恰當的","適當的"],"en":["suitable or proper in the circumstances","suitable or proper for the circumstances"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"propri","meaning":"own (自己的)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向自己所有的，即「適當的」。"}', 'appropriate measures/behavior/response; appropriate behavior / appropriate response', '[{"en":"Please dress in appropriate business attire.","zh-TW":"請穿著適當的商務服裝。"},{"en":"The manager took appropriate action.","zh-TW":"經理採取了適當的行動。"},{"en":"Jeans are not appropriate for a formal dinner.","zh-TW":"牛仔褲不適合正式晚宴。"},{"en":"Please wear appropriate clothing.","zh-TW":"請穿著合適的服裝。"}]', '{"adverb":"appropriately","noun":"appropriateness"}', NULL, 4, 190, 266),
(191, 'appropriation', '/əˌproʊpriˈeɪʃən/', 'noun', '{"zh-TW":["撥款；撥用"],"en":["the setting aside of funds for a specific purpose or authorized use"]}', NULL, 'budget appropriation / government appropriation', '[{"en":"The board approved the appropriation of $2 million for the R&D project.","zh-TW":"董事會批准了200萬元用於研發項目的撥款。"},{"en":"Government appropriations for infrastructure were increased in the budget.","zh-TW":"預算中增加了用於基礎設施的政府撥款。"}]', '{"verb":"appropriate"}', NULL, 5, 191, NULL),
(192, 'approval', '/əˈpruːvəl/', 'noun', '{"zh-TW":["批准；認可"],"en":["official agreement or permission"]}', NULL, 'require approval / pending approval', '[{"en":"Final approval is required from the board of directors.","zh-TW":"需要董事會的最終批准。"},{"en":"The budget proposal awaits management approval.","zh-TW":"預算提案正等待管理層批准。"}]', '{"verb":"approve","adjective":"approved"}', NULL, 3, 192, 9),
(193, 'approve', '/əˈpruːv/', 'verb', '{"zh-TW":["批准；核准","贊成"],"en":["to officially agree to or accept","to believe that something is good"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"prove","meaning":"test/good (驗證/好)"},"logic":"朝向好的，即「批准」。"}', 'approve a request/budget/plan', '[{"en":"The board approved the annual budget.","zh-TW":"董事會批准了年度預算。"},{"en":"The proposal was approved unanimously.","zh-TW":"該提案被一致通過。"}]', '{"noun":"approval"}', NULL, 3, 193, NULL),
(194, 'approved', 'əˈpruːvd', 'adjective', '{"zh-TW":["已批准的；獲批的","認可的"],"en":["officially accepted","meeting required standards"]}', NULL, 'approved supplier/approved budget', '[{"en":"Only approved vendors may be used.","zh-TW":"只能使用已批准的供應商。"}]', '{"verb":"approve","noun":"approval"}', NULL, 3, 194, NULL),
(195, 'approximate', '/əˈprɒksɪmət/', 'adjective', '{"zh-TW":["大約的；近似的"],"en":["close to the actual but not completely exact"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proxim","meaning":"nearest (最近)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向最近的，即「近似的」。"}', 'approximate cost/time/value', '[{"en":"The approximate cost of the project is $500,000.","zh-TW":"該專案的大約成本為50萬美元。"},{"en":"Can you give me an approximate delivery date?","zh-TW":"你能給我一個大約的交貨日期嗎？"}]', '{"adverb":"approximately","noun":"approximation"}', NULL, 4, 195, NULL),
(196, 'approximately', '/əˈprɒksɪmətli/', 'adverb', '{"zh-TW":["大約"],"en":["close to an exact amount but not completely accurate"]}', '{"prefix":{"text":"ap-","meaning":"to (朝向)"},"root":{"text":"proxim","meaning":"near (接近)"},"suffix":{"text":"-ately","meaning":"in manner of (以…方式)"},"logic":"以接近的方式，即「大約」。"}', 'approximately 100 / takes approximately', '[{"en":"The project will take approximately six months.","zh-TW":"這個專案大約需要六個月。"},{"en":"Approximately 200 people attended the event.","zh-TW":"大約200人參加了活動。"}]', '{"adjective":"approximate","verb":"approximate","noun":"approximation"}', NULL, 5, 196, 10),
(197, 'apt', '/æpt/', 'adjective', '{"zh-TW":["恰當的；適合的"],"en":["appropriate or suitable in the circumstances"]}', NULL, 'apt description / apt choice', '[{"en":"She made an apt comparison between the two strategies.","zh-TW":"她在兩種策略之間做了恰當的比較。"},{"en":"His concise summary was an apt way to end the presentation.","zh-TW":"他的簡明摘要是結束簡報的恰當方式。"}]', '{"adverb":"aptly","noun":"aptness"}', NULL, 1, 197, NULL),
(198, 'arbitrage', '/ˈɑːrbɪtrɑːʒ/', 'noun', '{"zh-TW":["套利"],"en":["profiting from price differences of the same asset in different markets"]}', NULL, 'risk arbitrage / currency arbitrage / exploit arbitrage opportunities', '[{"en":"Traders engage in arbitrage to profit from price discrepancies.","zh-TW":"交易者進行套利以從價格差異中獲利。"},{"en":"Arbitrage opportunities quickly disappear in efficient markets.","zh-TW":"套利機會在有效市場中迅速消失。"}]', '{"verb":"arbitrage","noun":"arbitrageur"}', NULL, 3, 198, NULL),
(199, 'arbitrate', '/ˈɑːrbɪtreɪt/', 'verb', '{"zh-TW":["仲裁；裁決"],"en":["to act as an impartial judge to resolve a dispute between parties"]}', NULL, 'arbitrate a dispute / arbitrate between parties', '[{"en":"An independent expert was appointed to arbitrate the contract dispute.","zh-TW":"任命了一名獨立專家仲裁合約糾紛。"},{"en":"The two sides agreed to arbitrate rather than go to court.","zh-TW":"雙方同意進行仲裁而不是上法院。"}]', '{"noun":"arbitration","noun2":"arbitrator"}', NULL, 3, 199, 646);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(200, 'arbitration', '/ˌɑːrbɪˈtreɪʃən/', 'noun', '{"zh-TW":["仲裁"],"en":["a method of resolving disputes outside of court using a neutral third party"]}', NULL, 'binding arbitration / arbitration clause / submit to arbitration / arbitration hearing', '[{"en":"The contract included an arbitration clause to resolve disputes.","zh-TW":"合約包含仲裁條款以解決糾紛。"},{"en":"Arbitration is faster and cheaper than litigation for commercial disputes.","zh-TW":"仲裁比訴訟更快且更便宜解決商業糾紛。"}]', '{"verb":"arbitrate","noun":"arbitrator"}', NULL, 4, 200, 749),
(201, 'arbitrator', '/ˈɑːrbɪtreɪtər/', 'noun', '{"zh-TW":["仲裁人；仲裁員"],"en":["an independent person appointed to settle a dispute"]}', NULL, 'appoint an arbitrator / neutral arbitrator', '[{"en":"An independent arbitrator was appointed to resolve the pay dispute.","zh-TW":"任命了一名獨立仲裁員解決薪資糾紛。"},{"en":"The arbitrator''s decision is binding on both parties.","zh-TW":"仲裁員的裁決對雙方均具有約束力。"}]', '{"verb":"arbitrate","noun":"arbitration"}', NULL, 4, 201, NULL),
(202, 'architect', '/ˈɑːrkɪtekt/', 'noun', '{"zh-TW":["建築師"],"en":["a person who designs buildings"]}', '{"prefix":{"text":"archi-","meaning":"chief (首席)"},"root":{"text":"tect","meaning":"builder (建造者)"},"logic":"首席建造者，即「建築師」。"}', 'architect firm / landscape architect', '[{"en":"The architect designed a modern office building.","zh-TW":"建築師設計了一棟現代辦公大樓。"},{"en":"She hired an architect to redesign her home.","zh-TW":"她聘請建築師重新設計她的房子。"}]', '{"noun":"architecture","adjective":"architectural"}', NULL, 3, 202, NULL),
(203, 'archive', '/ˈɑːrkaɪv/', 'noun', '{"zh-TW":["檔案庫；存檔"],"en":["a collection of historical documents or records"]}', NULL, 'company archive / archive files', '[{"en":"All contracts are stored in the company archive.","zh-TW":"所有合約都存放在公司檔案庫中。"},{"en":"Please archive the completed project files.","zh-TW":"請將已完成的項目文件存檔。"}]', '{"verb":"archive","adjective":"archived"}', NULL, 3, 203, 825),
(204, 'area', '/ˈɛriə/', 'noun', '{"zh-TW":["區域；面積"],"en":["a particular part of a place or subject"]}', NULL, 'in the area / area of expertise', '[{"en":"This area is known for its food.","zh-TW":"這個地區以美食聞名。"},{"en":"What''s the area of this room?","zh-TW":"這個房間的面積是多少？"}]', NULL, NULL, 1, 204, NULL),
(205, 'arise', '/əˈraɪz/', 'verb', '{"zh-TW":["出現；產生","出現；發生"],"en":["to come into being or to come to attention","to come into being; to occur"]}', '{"prefix":{"text":"a-","meaning":"up (向上)"},"root":{"text":"rise","meaning":"rise (升起)"},"logic":"升起來，即「出現」。"}', 'arise from / problems arise; problems arise / arise from / should the need arise', '[{"en":"Several issues arose during the negotiation.","zh-TW":"談判期間出現了幾個問題。"},{"en":"Opportunities may arise from this partnership.","zh-TW":"這個合作關係可能產生機會。"},{"en":"Unexpected problems arose during the project.","zh-TW":"專案期間出現了意料之外的問題。"},{"en":"Conflicts can arise from misunderstandings.","zh-TW":"衝突可能源於誤解。"}]', NULL, NULL, 2, 205, NULL),
(206, 'arm', '/ɑːrm/', 'noun', '{"zh-TW":["手臂；武器","手臂；武裝"],"en":["the body part from shoulder to hand","the body part between shoulder and hand; to supply with weapons"]}', NULL, 'arm in arm / open arms; arm in arm / armed with', '[{"en":"She broke her arm skiing.","zh-TW":"她滑雪時摔斷了手臂。"},{"en":"They welcomed us with open arms.","zh-TW":"他們張開雙臂歡迎我們。"},{"en":"She broke her arm in the accident.","zh-TW":"她在事故中摔斷了手臂。"},{"en":"The security guard was armed.","zh-TW":"保全人員有武裝。"}]', '{"noun":"armament","adjective":"armed, unarmed"}', NULL, 1, 206, NULL),
(207, 'army', '/ˈɑːrmi/', 'noun', '{"zh-TW":["軍隊；陸軍"],"en":["the military land forces of a country"]}', NULL, 'join the army / army base', '[{"en":"He joined the army at 18.","zh-TW":"他18歲參軍。"},{"en":"The army was deployed overseas.","zh-TW":"軍隊被部署到海外。"}]', NULL, NULL, 1, 207, NULL),
(208, 'around', '/əˈraʊnd/', 'preposition', '{"zh-TW":["周圍；大約"],"en":["on all sides of; approximately"]}', NULL, 'around the world / look around', '[{"en":"There are trees around the house.","zh-TW":"房子周圍有樹。"},{"en":"It costs around fifty dollars.","zh-TW":"大約花費五十美元。"}]', NULL, NULL, 2, 208, NULL),
(209, 'arrange', '/əˈreɪndʒ/', 'verb', '{"zh-TW":["安排；籌備"],"en":["to plan or organize something in advance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"range","meaning":"rank/row (排列)"},"logic":"朝向排列，即「安排」。"}', 'arrange a meeting/event/delivery', '[{"en":"I''ll arrange a meeting with the client for next week.","zh-TW":"我會安排下週與客戶的會議。"},{"en":"Transportation has been arranged for all attendees.","zh-TW":"已為所有出席者安排了交通。"}]', '{"noun":"arrangement"}', NULL, 3, 209, 267),
(210, 'arrears', '/əˈrɪərz/', 'noun', '{"zh-TW":["欠款；拖欠款項"],"en":["unpaid debts or obligations that are overdue"]}', NULL, 'fall into arrears / pay off arrears', '[{"en":"The customer fell three months into arrears on the loan.","zh-TW":"客戶的貸款拖欠了三個月。"},{"en":"The company cleared all arrears on its supplier accounts.","zh-TW":"公司清除了供應商帳戶上的所有欠款。"}]', '{"singular":"arrearage"}', NULL, 3, 210, NULL),
(211, 'arrive', '/əˈraɪv/', 'verb', '{"zh-TW":["到達；抵達"],"en":["to reach a destination","to reach a place after traveling"]}', NULL, 'arrive at / arrive on time; arrive at/in + 地點', '[{"en":"The shipment will arrive tomorrow.","zh-TW":"貨物明天會到達。"},{"en":"Please arrive 10 minutes early.","zh-TW":"請提前10分鐘到達。"},{"en":"The flight arrives at 3 PM.","zh-TW":"班機下午三點抵達。"},{"en":"We arrived in Tokyo yesterday.","zh-TW":"我們昨天到達東京。"}]', '{"verb":"arrive","noun":"arrival"}', NULL, 2, 211, NULL),
(212, 'arrogant', '/ˈærəɡənt/', 'adjective', '{"zh-TW":["傲慢的"],"en":["having an exaggerated sense of one''s importance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"rog","meaning":"ask/claim (要求)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對自己提出過高要求的，即「傲慢的」。"}', 'arrogant attitude / arrogant behavior', '[{"en":"His arrogant attitude made him unpopular.","zh-TW":"他傲慢的態度使他不受歡迎。"},{"en":"Don''t be so arrogant about your achievements.","zh-TW":"不要對你的成就如此傲慢。"}]', '{"noun":"arrogance"}', NULL, 3, 212, NULL),
(213, 'art', '/ɑːrt/', 'noun', '{"zh-TW":["藝術；美術"],"en":["the creation of beautiful or meaningful things"]}', NULL, 'work of art / art gallery', '[{"en":"She studies art at university.","zh-TW":"她在大學學藝術。"},{"en":"This painting is a true work of art.","zh-TW":"這幅畫是真正的藝術品。"}]', '{"noun":"artist","adjective":"artistic"}', NULL, 1, 213, NULL),
(214, 'articulate', '/ɑːrˈtɪkjʊleɪt/', 'verb', '{"zh-TW":["清楚地表達；闡述"],"en":["to express clearly and effectively"]}', NULL, 'articulate a vision / articulate concerns', '[{"en":"She articulated the company''s strategy clearly to investors.","zh-TW":"她向投資者清楚地闡述了公司的策略。"},{"en":"The manager articulated concerns about the project timeline.","zh-TW":"經理清楚地表達了對項目時間表的顧慮。"}]', '{"adjective":"articulate","adverb":"articulately"}', NULL, 4, 214, 955),
(215, 'artifact', '/ˈɑːrtɪfækt/', 'noun', '{"zh-TW":["文物；人工製品"],"en":["an object made by a human, especially one of historical interest"]}', '{"root":{"text":"arti","meaning":"skill (技藝)"},"suffix":{"text":"fact","meaning":"made (製造)"},"logic":"用技藝製造的東西，即「工藝品」。"}', 'ancient artifact / cultural artifact', '[{"en":"The museum displays artifacts from ancient Egypt.","zh-TW":"博物館展示古埃及文物。"},{"en":"Archaeologists discovered several artifacts at the site.","zh-TW":"考古學家在遺址發現了數件文物。"}]', NULL, NULL, 3, 215, NULL),
(216, 'artificial', '/ˌɑːrtɪˈfɪʃəl/', 'adjective', '{"zh-TW":["人工的；人造的"],"en":["made by people; not natural","made by humans rather than occurring naturally"]}', '{"root":{"text":"arti","meaning":"skill/craft (技藝)"},"suffix":{"text":"-ficial","meaning":"making (製造)"},"logic":"用技藝製造的，即「人工的」。"}', 'artificial intelligence / artificial flavor', '[{"en":"Artificial intelligence is changing the world.","zh-TW":"人工智慧正在改變世界。"},{"en":"The flowers are artificial.","zh-TW":"這些花是人造的。"},{"en":"The lake is artificial, not natural.","zh-TW":"這個湖是人工的，不是天然的。"},{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多產業。"}]', '{"adverb":"artificially"}', NULL, 4, 216, NULL),
(217, 'ask', '/ɑːsk/', 'verb', '{"zh-TW":["詢問；要求；邀請"],"en":["to say something to get an answer; to request"]}', NULL, 'ask for / ask sb to do sth / ask about', '[{"en":"Can I ask you a question?","zh-TW":"我可以問你一個問題嗎？"},{"en":"She asked for a raise.","zh-TW":"她要求加薪。"}]', NULL, NULL, 1, 217, NULL),
(218, 'aspect', '/ˈæspekt/', 'noun', '{"zh-TW":["方面；層面"],"en":["a particular part or feature of something"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"spect","meaning":"look (看)"},"logic":"從某個方向看過去的面向，即「方面」。"}', 'important aspect / every aspect / key aspect', '[{"en":"We need to consider every aspect of the problem.","zh-TW":"我們需要考慮問題的每個方面。"},{"en":"Safety is the most important aspect of the job.","zh-TW":"安全是這份工作最重要的面向。"}]', NULL, NULL, 2, 218, NULL),
(219, 'assemble', '/əˈsembl/', 'verb', '{"zh-TW":["組裝；集合"],"en":["to fit together the parts of","to come together in one place","to put together the parts of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"semble","meaning":"together (一起)"},"logic":"朝向一起，即「組裝、集合」。"}', 'assemble a team/product/parts; assemble a team / assemble furniture', '[{"en":"Workers assemble the components on the factory floor.","zh-TW":"工人在工廠車間組裝零件。"},{"en":"The committee assembled to discuss the proposal.","zh-TW":"委員會集合討論該提案。"},{"en":"Workers assemble the products on the factory floor.","zh-TW":"工人在工廠樓層組裝產品。"},{"en":"The team assembled in the conference room.","zh-TW":"團隊在會議室集合。"}]', '{"noun":"assembly"}', NULL, 3, 219, 648),
(220, 'assert', '/əˈsɜːrt/', 'verb', '{"zh-TW":["斷言；主張"],"en":["to state something clearly and firmly"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sert","meaning":"join/bind (結合)"},"logic":"朝向牢固結合的聲明，即「斷言」。"}', 'assert rights/authority/claims', '[{"en":"The company asserted its right to the patent.","zh-TW":"公司主張其專利權。"},{"en":"She asserted that the data was accurate.","zh-TW":"她斷言資料是準確的。"}]', '{"noun":"assertion","adjective":"assertive"}', NULL, 2, 220, NULL),
(221, 'assess', '/əˈses/', 'verb', '{"zh-TW":["評估；估算"],"en":["to evaluate or estimate the nature or quality of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sess","meaning":"sit (坐)"},"logic":"坐下來朝向審視，即「評估」。"}', 'assess risk/damage/performance', '[{"en":"We need to assess the potential risks before investing.","zh-TW":"投資前我們需要評估潛在風險。"},{"en":"The damage was assessed at $2 million.","zh-TW":"損失估計為200萬美元。"}]', '{"noun":"assessment"}', NULL, 2, 221, NULL),
(222, 'assessment', '/əˈsesmənt/', 'noun', '{"zh-TW":["評估；鑑定"],"en":["the process of evaluating performance, risk, or capability"]}', NULL, 'risk assessment / needs assessment / performance assessment / conduct an assessment', '[{"en":"A comprehensive risk assessment was conducted before the project launch.","zh-TW":"在項目啟動前進行了全面的風險評估。"},{"en":"The assessment revealed gaps in the team''s technical skills.","zh-TW":"評估揭示了團隊技術技能方面的差距。"}]', '{"verb":"assess","noun":"assessor"}', NULL, 4, 222, 268),
(223, 'asset', '/ˈæset/', 'noun', '{"zh-TW":["資產"],"en":["any resource owned by a company with economic value"]}', NULL, 'current asset / fixed asset / intangible asset / asset management / asset valuation', '[{"en":"The company''s most valuable asset is its brand reputation.","zh-TW":"公司最有價值的資產是其品牌聲譽。"},{"en":"Total assets on the balance sheet exceeded $1 billion.","zh-TW":"資產負債表上的總資產超過10億美元。"}]', '{"plural":"assets","adjective":"asset-rich"}', NULL, 2, 223, 269),
(224, 'assign', '/əˈsaɪn/', 'verb', '{"zh-TW":["分配；指派"],"en":["to give someone a particular job or task"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sign","meaning":"mark (標記)"},"logic":"朝向標記某人做某事，即「指派」。"}', 'assign a task/role/responsibility', '[{"en":"The manager assigned the task to the new employee.","zh-TW":"經理將任務分配給新員工。"},{"en":"Each team member was assigned a specific role.","zh-TW":"每位團隊成員被指派了特定角色。"}]', '{"noun":"assignment"}', NULL, 2, 224, 270),
(225, 'assigned', 'əˈsaɪnd', 'adjective', '{"zh-TW":["指定的；分配的","負責的"],"en":["given a specific task","allocated"]}', NULL, 'assigned tasks/assigned responsibilities', '[{"en":"Complete your assigned tasks on time.","zh-TW":"按時完成您的指定任務。"}]', '{"verb":"assign","noun":"assignment"}', NULL, 3, 225, NULL),
(226, 'assignment', '/əˈsaɪnmənt/', 'noun', '{"zh-TW":["作業；任務"],"en":["a task given as part of a job or studies"]}', NULL, 'homework assignment / complete an assignment', '[{"en":"The assignment is due on Friday.","zh-TW":"作業週五到期。"},{"en":"She completed all her assignments on time.","zh-TW":"她按時完成了所有作業。"}]', '{"verb":"assign"}', NULL, 4, 226, 508),
(227, 'assist', '/əˈsɪst/', 'verb', '{"zh-TW":["協助；幫助"],"en":["to help or give support to someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"站在旁邊支持，即「協助」。"}', 'assist with / assist in doing', '[{"en":"Our team will assist you with the transition.","zh-TW":"我們的團隊將協助您完成過渡。"},{"en":"Can I assist you in finding what you need?","zh-TW":"我能幫您找到您需要的東西嗎？"}]', '{"noun":"assistance","noun2":"assistant"}', NULL, 2, 227, 73),
(228, 'assistance', 'əˈsɪstəns', 'noun', '{"zh-TW":["協助；幫助","支援"],"en":["help or support given","aid provided"]}', NULL, 'technical assistance/request assistance', '[{"en":"Please call us if you need any assistance.","zh-TW":"如果您需要任何幫助，請致電。"}]', '{"verb":"assist","adjective":"assistive"}', NULL, 4, 228, NULL),
(229, 'associate', '/əˈsəʊsieɪt/', 'verb', '{"zh-TW":["聯想；關聯","交往"],"en":["to connect in one''s mind","to spend time with someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"soci","meaning":"companion (夥伴)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為夥伴，即「關聯」。"}', 'associate with / be associated with', '[{"en":"Customers associate the brand with quality.","zh-TW":"顧客將該品牌與品質聯繫在一起。"},{"en":"High stress is associated with health problems.","zh-TW":"高壓力與健康問題有關。"}]', '{"noun":"association"}', NULL, 3, 229, NULL),
(230, 'assume', '/əˈsjuːm/', 'verb', '{"zh-TW":["假設；承擔"],"en":["to suppose to be true without proof","to take on responsibility"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"朝向拿取（未證實的），即「假設」。"}', 'assume responsibility/role/risk', '[{"en":"Let''s assume the project will take six months.","zh-TW":"我們假設這個專案需要六個月。"},{"en":"She assumed the role of department head.","zh-TW":"她承擔了部門主管的角色。"}]', '{"noun":"assumption"}', NULL, 2, 230, NULL),
(231, 'assumption', '/əˈsʌmpʃən/', 'noun', '{"zh-TW":["假設；前提"],"en":["a condition believed to be true without verification, used in planning"]}', NULL, 'project assumption / document assumptions / challenge an assumption', '[{"en":"All project assumptions were recorded in the project charter.","zh-TW":"所有項目假設都記錄在項目章程中。"},{"en":"Failing to validate assumptions early caused the project to fail.","zh-TW":"未能早期驗證假設導致項目失敗。"}]', '{"plural":"assumptions","verb":"assume"}', NULL, 4, 231, 509),
(232, 'assure', '/əˈʃʊər/', 'verb', '{"zh-TW":["保證；使確信","向…保證；確保"],"en":["to tell someone confidently to remove doubt","to tell someone confidently that something is true"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"朝向使人確定，即「保證」。"}', 'assure sb that / rest assured; assure someone that / rest assured / I assure you', '[{"en":"I assure you that the issue will be resolved promptly.","zh-TW":"我向您保證問題將盡快解決。"},{"en":"Rest assured, your data is secure.","zh-TW":"請放心，您的資料是安全的。"},{"en":"I assure you the problem will be fixed.","zh-TW":"我向你保證問題會被解決。"},{"en":"Rest assured, your data is safe.","zh-TW":"請放心，你的資料是安全的。"}]', '{"noun":"assurance","adjective":"assured"}', NULL, 2, 232, 728),
(233, 'athlete', '/ˈæθliːt/', 'noun', '{"zh-TW":["運動員"],"en":["a person who is good at sports"]}', NULL, 'professional athlete / athlete''s performance', '[{"en":"She is a talented athlete.","zh-TW":"她是一位有天賦的運動員。"},{"en":"The athlete broke the world record.","zh-TW":"那位運動員打破了世界紀錄。"}]', '{"adjective":"athletic","noun2":"athletics"}', NULL, 3, 233, NULL),
(234, 'ATM', '/eɪ tiː ɛm/', 'noun', '{"zh-TW":["自動提款機"],"en":["a machine that allows bank customers to withdraw cash"]}', NULL, 'use an ATM / ATM withdrawal', '[{"en":"She withdrew cash from the ATM near the hotel.","zh-TW":"她在飯店附近的自動提款機提取了現金。"},{"en":"ATM fees apply when using machines outside your network.","zh-TW":"使用網絡外的機器時需支付自動提款機手續費。"}]', NULL, NULL, 1, 234, NULL),
(235, 'atmosphere', '/ˈætməsfɪr/', 'noun', '{"zh-TW":["大氣層；氣氛"],"en":["the layer of gases around the earth","the mood or feeling of a place"]}', '{"root":{"text":"atmos","meaning":"vapor (蒸氣)"},"suffix":{"text":"sphere","meaning":"ball (球)"},"logic":"蒸氣包圍的球體，即「大氣層」。"}', 'earth''s atmosphere / friendly atmosphere', '[{"en":"The atmosphere at the party was lively.","zh-TW":"派對的氣氛很活絡。"},{"en":"Pollution is damaging the atmosphere.","zh-TW":"汙染正在破壞大氣層。"}]', '{"adjective":"atmospheric"}', NULL, 4, 235, NULL),
(236, 'atrium', '/ˈeɪtriəm/', 'noun', '{"zh-TW":["中庭大廳"],"en":["a large open space inside a building"]}', NULL, 'hotel atrium / glass atrium', '[{"en":"The hotel has a stunning glass atrium with natural light.","zh-TW":"飯店有令人驚嘆的玻璃中庭，採光自然。"},{"en":"Guests can relax in the central atrium.","zh-TW":"賓客可以在中央中庭休息。"}]', NULL, NULL, 2, 236, NULL),
(237, 'attach', '/əˈtætʃ/', 'verb', '{"zh-TW":["附上；連接"],"en":["to fasten or join one thing to another"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tach","meaning":"stake/fasten (釘住)"},"logic":"朝向釘住，即「附上」。"}', 'attach a file/document/label', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看附在此電子郵件中的報告。"},{"en":"Attach the receipt to your expense claim.","zh-TW":"請將收據附在您的報銷申請上。"}]', '{"noun":"attachment"}', NULL, 2, 237, NULL),
(238, 'attached', '/əˈtætʃt/', 'adjective', '{"zh-TW":["附件的；附上的"],"en":["joined or fastened to something; included with a message"]}', NULL, 'as attached / please find attached', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看此電子郵件的附件報告。"},{"en":"The attached document outlines the terms of the agreement.","zh-TW":"附件文件概述了協議條款。"}]', '{"verb":"attach","noun":"attachment"}', NULL, 3, 238, NULL),
(239, 'attachment', '/əˈtætʃmənt/', 'noun', '{"zh-TW":["附件；附加物"],"en":["a file sent along with an email or document"]}', NULL, 'email attachment / download the attachment', '[{"en":"Please open the attachment for the full report.","zh-TW":"請打開附件查看完整報告。"},{"en":"The attachment contains all the required forms.","zh-TW":"附件包含所有所需的表格。"}]', '{"verb":"attach","adjective":"attached"}', NULL, 4, 239, 510),
(240, 'attack', '/əˈtæk/', 'noun', '{"zh-TW":["攻擊；發作"],"en":["an act of violence against someone"]}', NULL, 'heart attack / under attack', '[{"en":"The city was under attack.","zh-TW":"城市遭受了攻擊。"},{"en":"He suffered a heart attack.","zh-TW":"他心臟病發作了。"}]', '{"verb":"attack","noun2":"attacker"}', NULL, 2, 240, NULL),
(241, 'attain', '/əˈteɪn/', 'verb', '{"zh-TW":["達到；獲得"],"en":["to succeed in achieving something after effort"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有，即「達到」。"}', 'attain a goal/level/standard', '[{"en":"Few companies attain such high customer satisfaction ratings.","zh-TW":"很少有公司達到如此高的客戶滿意度。"},{"en":"He attained the rank of senior vice president.","zh-TW":"他達到了資深副總裁的職位。"}]', '{"adjective":"attainable","noun":"attainment"}', NULL, 2, 241, NULL),
(242, 'attempt', '/əˈtempt/', 'verb', '{"zh-TW":["嘗試；企圖"],"en":["to try to do something, especially difficult","to try to do something"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tempt","meaning":"try (嘗試)"},"logic":"朝向嘗試，即「企圖」。"}', 'attempt to do / make an attempt; attempt to / first attempt / make an attempt', '[{"en":"The company attempted to enter the European market.","zh-TW":"公司嘗試進入歐洲市場。"},{"en":"Several attempts were made to resolve the dispute.","zh-TW":"多次嘗試解決爭端。"},{"en":"He attempted to climb the mountain alone.","zh-TW":"他嘗試獨自攀登那座山。"},{"en":"She passed the exam on her first attempt.","zh-TW":"她第一次嘗試就通過了考試。"}]', '{"noun":"attempt"}', NULL, 3, 242, NULL),
(243, 'attend', '/əˈtend/', 'verb', '{"zh-TW":["【主要意義-動詞】出席；參加","【次要意義-動詞】照料；服侍；護理（病人）","【次要意義-動詞】處理；注意（attend to）"],"en":["[primary] to be present at an event or place","[secondary] to care for someone who is sick or in need","[secondary] to deal with something; to give attention to"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tend","meaning":"stretch (延伸)"},"logic":"朝向延伸注意力，即「出席」。"}', 'attend to a matter / attend to a customer / attend on someone', '[{"en":"A doctor attended to the injured worker on site.","zh-TW":"現場有醫生照料受傷的工人。"},{"en":"Please attend to the urgent client inquiry before anything else.","zh-TW":"請在處理其他事情之前先處理緊急的客戶詢問。"},{"en":"The sales representative attended to each customer personally.","zh-TW":"銷售代表親自服務每位顧客。"}]', '{"noun":"attendant, attendance","adjective":"attentive"}', 'attend to = 「照料/服侍/處理」，不同於 attend（出席），是 TOEIC 客服或醫療文章中的陷阱用法，attendant（服務員/侍者）的詞根含義也源於此。', 2, 243, NULL),
(244, 'attention', '/əˈtɛnʃən/', 'noun', '{"zh-TW":["注意力；關注","注意；關注"],"en":["the act of concentrating on something","the act of thinking about or watching something carefully"]}', NULL, 'pay attention / draw attention to; pay attention to / attract/draw attention', '[{"en":"Pay attention to the safety guidelines.","zh-TW":"請注意安全指南。"},{"en":"The report drew attention to the issue.","zh-TW":"報告引起了人們對該問題的關注。"},{"en":"Please pay attention to the instructions.","zh-TW":"請注意指示。"},{"en":"The advertisement attracted a lot of attention.","zh-TW":"這則廣告引起了很多關注。"}]', '{"noun":"attention","adjective":"attentive","adverb":"attentively"}', NULL, 3, 244, NULL),
(245, 'attitude', '/ˈætɪtjuːd/', 'noun', '{"zh-TW":["態度；看法"],"en":["a settled way of thinking or feeling about something"]}', '{"root":{"text":"apt","meaning":"fit (適合)"},"suffix":{"text":"-itude","meaning":"state (狀態)"},"logic":"適合的狀態展現，即「態度」。"}', 'positive/negative attitude / attitude toward', '[{"en":"A positive attitude is valued in the workplace.","zh-TW":"工作場所重視積極的態度。"},{"en":"Her attitude toward work impressed her supervisors.","zh-TW":"她對工作的態度令主管印象深刻。"}]', NULL, NULL, 3, 245, NULL),
(246, 'attorney', '/əˈtɜːrni/', 'noun', '{"zh-TW":["律師"],"en":["a person qualified to practice law"]}', NULL, 'attorney general / defense attorney', '[{"en":"She hired an attorney.","zh-TW":"她請了一位律師。"},{"en":"The attorney general issued a statement.","zh-TW":"總檢察長發表了聲明。"}]', NULL, NULL, 3, 246, NULL),
(247, 'attract', '/əˈtrækt/', 'verb', '{"zh-TW":["吸引；招引","吸引"],"en":["to cause to come to a place or participate","to draw someone''s attention or interest"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tract","meaning":"draw/pull (拉)"},"logic":"朝向拉來，即「吸引」。"}', 'attract customers/investors/talent; attract attention / attract customers / attract investment', '[{"en":"The campaign attracted thousands of new customers.","zh-TW":"該活動吸引了數千名新客戶。"},{"en":"We need to attract top talent to remain competitive.","zh-TW":"我們需要吸引頂尖人才以保持競爭力。"},{"en":"The new store attracted many customers.","zh-TW":"新店吸引了許多顧客。"},{"en":"Bright colors attract children''s attention.","zh-TW":"鮮艷的顏色吸引孩子的注意力。"}]', '{"noun":"attraction","adjective":"attractive"}', NULL, 3, 247, 272),
(248, 'attribute', '/əˈtrɪbjuːt/', 'verb', '{"zh-TW":["歸因於；認為是"],"en":["to regard something as being caused by"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tribute","meaning":"assign (分配)"},"logic":"朝向分配原因，即「歸因於」。"}', 'attribute success/failure to', '[{"en":"She attributes her success to hard work and determination.","zh-TW":"她將成功歸因於努力和決心。"},{"en":"The decline was attributed to market conditions.","zh-TW":"下降被歸因於市場狀況。"}]', '{"noun":"attribution"}', NULL, 3, 248, 650),
(249, 'attrition', '/əˈtrɪʃən/', 'noun', '{"zh-TW":["自然減員；磨損"],"en":["the reduction in staff through voluntary departures without replacement"]}', NULL, 'natural attrition / attrition rate / high attrition', '[{"en":"The company relied on attrition rather than layoffs to reduce headcount.","zh-TW":"公司依靠自然減員而非裁員來減少人數。"},{"en":"High attrition in the sales team raised concerns about culture.","zh-TW":"銷售團隊的高自然減員率引發了對企業文化的擔憂。"}]', '{"adjective":"attritive"}', NULL, 3, 249, 750);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(250, 'auction', '/ˈɔːkʃən/', 'noun', '{"zh-TW":["拍賣"],"en":["a public sale in which goods or property are sold to the highest bidder"]}', NULL, 'public auction / online auction / put up for auction', '[{"en":"The seized assets were sold at a public auction.","zh-TW":"被沒收的資產在公開拍賣會上出售。"},{"en":"She won the bid at the online auction for the collectibles.","zh-TW":"她在線上拍賣會上以最高出價獲得了藏品。"}]', '{"verb":"auction","noun":"auctioneer"}', NULL, 3, 250, NULL),
(251, 'audience', '/ˈɔːdiəns/', 'noun', '{"zh-TW":["觀眾；聽眾"],"en":["people watching or listening to a performance"]}', NULL, 'target audience / live audience', '[{"en":"The audience applauded loudly.","zh-TW":"觀眾大聲鼓掌。"},{"en":"The show attracted a large audience.","zh-TW":"這個節目吸引了大量觀眾。"}]', NULL, NULL, 3, 251, NULL),
(252, 'audit', '/ˈɔːdɪt/', 'noun', '{"zh-TW":["審計；稽核"],"en":["an official examination of accounts or processes"]}', '{"root":{"text":"audit","meaning":"hear (聽)"},"logic":"最初為聽取帳目報告，即「審計」。"}', 'conduct an audit / annual audit', '[{"en":"The firm conducts an annual financial audit.","zh-TW":"該公司進行年度財務審計。"},{"en":"An internal audit revealed several discrepancies.","zh-TW":"內部稽核揭露了幾項差異。"}]', '{"noun":"auditor"}', NULL, 2, 252, 273),
(253, 'auditor', '/ˈɔːdɪtər/', 'noun', '{"zh-TW":["審計師；稽核人員"],"en":["a person who conducts an official examination of financial records"]}', NULL, 'external auditor / internal auditor / appoint an auditor', '[{"en":"The auditor found discrepancies in the accounts.","zh-TW":"審計師在帳目中發現了差異。"},{"en":"The firm''s auditor issued a clean audit opinion.","zh-TW":"公司的審計師發表了無保留意見。"}]', '{"plural":"auditors"}', NULL, 3, 253, NULL),
(254, 'austerity', '/ɒˈsterɪti/', 'noun', '{"zh-TW":["緊縮；節約"],"en":["government policies cutting spending to reduce budget deficits"]}', NULL, 'austerity measures / period of austerity / implement austerity', '[{"en":"The government introduced austerity measures to reduce the deficit.","zh-TW":"政府引入緊縮措施以削減赤字。"},{"en":"Years of austerity reduced public services significantly.","zh-TW":"多年的緊縮政策顯著縮減了公共服務。"}]', '{"adjective":"austere"}', NULL, 3, 254, NULL),
(255, 'authentic', '/ɔːˈθentɪk/', 'adjective', '{"zh-TW":["真實的；正宗的"],"en":["genuine; of undisputed origin"]}', '{"root":{"text":"authent","meaning":"original (原始的)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與原始真實相關的，即「正宗的」。"}', 'authentic cuisine / authentic experience', '[{"en":"This restaurant serves authentic Italian food.","zh-TW":"這家餐廳供應正宗義大利料理。"},{"en":"Is this an authentic Gucci bag?","zh-TW":"這是正品Gucci包嗎？"}]', '{"noun":"authenticity","adverb":"authentically"}', NULL, 3, 255, NULL),
(256, 'authenticate', 'ɔːˈθɛntɪkeɪt', 'verb', '{"zh-TW":["驗證；認證","確認真實性"],"en":["to prove something is genuine","to verify"]}', NULL, 'authenticate a user/authenticate documents', '[{"en":"Please authenticate your identity.","zh-TW":"請驗證您的身份。"}]', '{"noun":"authentication","adjective":"authenticated"}', NULL, 4, 256, NULL),
(257, 'authority', '/ɔːˈθɒrəti/', 'noun', '{"zh-TW":["權威；當局"],"en":["the power to give orders","an organization with official power"]}', '{"root":{"text":"author","meaning":"originator (創始者)"},"suffix":{"text":"-ity","meaning":"state of (狀態)"},"logic":"身為創始者的地位，即「權威」。"}', 'local authority / authority figure / have authority', '[{"en":"The local authority approved the building plan.","zh-TW":"地方當局批准了建築計畫。"},{"en":"He spoke with authority on the subject.","zh-TW":"他在這個議題上很有權威。"}]', '{"adjective":"authoritative","verb":"authorize","noun2":"authorization"}', NULL, 3, 257, 274),
(258, 'authorization', '/ˌɔːθərɪˈzeɪʃən/', 'noun', '{"zh-TW":["授權；批准"],"en":["official permission or power to do something"]}', NULL, 'obtain authorization / require authorization', '[{"en":"Please obtain authorization before accessing restricted files.","zh-TW":"訪問受限文件前請先獲得授權。"},{"en":"Payment authorization was granted by the finance director.","zh-TW":"付款授權由財務主管批准。"}]', '{"verb":"authorize","adjective":"authorized"}', NULL, 5, 258, 511),
(259, 'authorize', '/ˈɔːθəraɪz/', 'verb', '{"zh-TW":["授權；批准"],"en":["to give official permission for something"]}', '{"root":{"text":"author","meaning":"creator (創造者)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為有權者，即「授權」。"}', 'authorize payment/access/use', '[{"en":"Only the director can authorize expenditures over $10,000.","zh-TW":"只有主管可以授權超過10,000美元的支出。"},{"en":"The transaction was not authorized.","zh-TW":"該交易未獲授權。"}]', '{"noun":"authorization","adjective":"authorized"}', NULL, 3, 259, 75),
(260, 'automated', 'ˈɔːtəmeɪtɪd', 'adjective', '{"zh-TW":["自動化的；自動的","機械化的"],"en":["using automatic equipment","operated without manual control"]}', NULL, 'automated system/automated report', '[{"en":"The automated system generates weekly reports.","zh-TW":"自動化系統每週生成報告。"}]', '{"verb":"automate","noun":"automation"}', NULL, 3, 260, NULL),
(261, 'automatic', '/ˌɔːtəˈmætɪk/', 'adjective', '{"zh-TW":["自動的"],"en":["operating by itself with little human control"]}', '{"root":{"text":"auto","meaning":"self (自己)"},"suffix":{"text":"-matic","meaning":"acting (行動的)"},"logic":"自己行動的，即「自動的」。"}', 'automatic update/renewal/response; automatic transmission / automatic reply / fully automatic', '[{"en":"The system sends automatic email confirmations.","zh-TW":"系統會發送自動電子郵件確認。"},{"en":"Payments are processed automatically each month.","zh-TW":"付款每月自動處理。"},{"en":"The doors open automatically.","zh-TW":"門會自動開啟。"},{"en":"The system sends automatic reminders.","zh-TW":"系統會發送自動提醒。"}]', '{"adverb":"automatically","noun":"automation","verb":"automate"}', NULL, 3, 261, NULL),
(262, 'automation', '/ˌɔːtəˈmeɪʃən/', 'noun', '{"zh-TW":["自動化"],"en":["using technology to perform tasks with minimal human intervention"]}', NULL, 'process automation / robotic automation / automation technology / workflow automation', '[{"en":"Automation reduced the time needed for data entry by 80%.","zh-TW":"自動化將數據輸入所需時間減少了80%。"},{"en":"The factory''s automation increased output while reducing labor costs.","zh-TW":"工廠自動化在降低勞動成本的同時提高了產量。"}]', '{"verb":"automate","adjective":"automated","noun":"automator"}', NULL, 4, 262, 275),
(263, 'autonomy', '/ɔːˈtɒnəmi/', 'noun', '{"zh-TW":["自主；自主權"],"en":["freedom to act independently without external control"]}', NULL, 'organizational autonomy / operational autonomy / give autonomy', '[{"en":"Subsidiaries operate with a high degree of autonomy.","zh-TW":"子公司以高度自主的方式運營。"},{"en":"Employees with more autonomy tend to show greater job satisfaction.","zh-TW":"擁有更多自主權的員工往往表現出更高的工作滿意度。"}]', '{"adjective":"autonomous","adverb":"autonomously"}', NULL, 3, 263, NULL),
(264, 'autumn', '/ˈɔːtəm/', 'noun', '{"zh-TW":["秋天"],"en":["the season between summer and winter"]}', NULL, 'autumn season / in autumn; in autumn / autumn leaves', '[{"en":"Sales typically increase in autumn.","zh-TW":"銷售額通常在秋季增加。"},{"en":"The autumn collection launches next week.","zh-TW":"秋季系列下週發布。"},{"en":"Leaves change color in autumn.","zh-TW":"秋天葉子會變色。"},{"en":"Autumn is my favorite season.","zh-TW":"秋天是我最喜歡的季節。"}]', '{"noun":"autumn","adjective":"autumnal"}', NULL, 2, 264, NULL),
(265, 'availability', '/əˌveɪləˈbɪlɪti/', 'noun', '{"zh-TW":["可用性；空房情況"],"en":["the state of being available or accessible"]}', NULL, 'room availability / check availability', '[{"en":"Please check room availability for the dates you need.","zh-TW":"請查看您所需日期的房間空房情況。"},{"en":"Availability is limited during the holiday season.","zh-TW":"假日期間可用性有限。"}]', '{"verb":"avail","adjective":"available"}', NULL, 4, 265, 957),
(266, 'available', '/əˈveɪləbl/', 'adjective', '{"zh-TW":["可用的；可獲得的"],"en":["able to be used or obtained"]}', '{"root":{"text":"avail","meaning":"be strong/be of use (有用)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠被使用的，即「可用的」。"}', 'available for / currently available', '[{"en":"The product is now available in all major stores.","zh-TW":"該產品現已在所有主要商店有售。"},{"en":"I''m available for a meeting on Thursday afternoon.","zh-TW":"我週四下午有空開會。"}]', '{"noun":"availability"}', NULL, 3, 266, 11),
(267, 'avalanche', '/ˈævəlæntʃ/', 'noun', '{"zh-TW":["雪崩"],"en":["a mass of snow falling rapidly down a mountainside"]}', '{"root":{"text":"avalanche","meaning":"descend (滑落)"},"logic":"源自法語 avaler（下降），指雪的快速滑落。"}', 'trigger an avalanche / avalanche warning', '[{"en":"The avalanche buried the entire village.","zh-TW":"雪崩掩埋了整個村莊。"},{"en":"Skiers should be aware of avalanche risks.","zh-TW":"滑雪者應注意雪崩風險。"}]', NULL, NULL, 3, 267, NULL),
(268, 'average', 'ˈævərɪdʒ', 'noun', '{"zh-TW":["平均；一般水準","平均值"],"en":["the middle value of a group","a usual level"]}', NULL, 'on average/industry average', '[{"en":"The average salary in this sector is high.","zh-TW":"這個行業的平均薪資很高。"}]', '{"adjective":"average","adverb":"on average"}', NULL, 3, 268, NULL),
(269, 'avoid', '/əˈvɔɪd/', 'verb', '{"zh-TW":["避免；迴避"],"en":["to keep away from or stop oneself from doing"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"void","meaning":"empty (空)"},"logic":"使離開空虛（危險），即「避免」。"}', 'avoid risk/mistakes/delays', '[{"en":"To avoid delays, please submit your documents early.","zh-TW":"為避免延遲，請提早提交文件。"},{"en":"The company took steps to avoid further losses.","zh-TW":"公司採取措施避免進一步損失。"}]', '{"adjective":"avoidable","noun":"avoidance"}', NULL, 2, 269, NULL),
(270, 'awake', '/əˈweɪk/', 'adjective', '{"zh-TW":["醒著的"],"en":["not sleeping"]}', NULL, 'wide awake / stay awake', '[{"en":"Are you still awake?","zh-TW":"你還醒著嗎？"},{"en":"I lay awake all night.","zh-TW":"我整晚都醒著。"}]', '{"verb":"awaken"}', NULL, 2, 270, NULL),
(271, 'award', '/əˈwɔːrd/', 'noun', '{"zh-TW":["獎項；獎金","授予","獎；獎項"],"en":["a prize given for achievement","to officially give something as a reward"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"ward","meaning":"guard/watch (看守)"},"logic":"朝向看守評定後給予，即「獎項」。"}', 'award a contract/prize/grant; award ceremony / win an award', '[{"en":"The contract was awarded to the lowest bidder.","zh-TW":"合約授予了最低出價者。"},{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲得獎項。"},{"en":"She won an award for best actress.","zh-TW":"她獲得了最佳女主角獎。"},{"en":"The awards ceremony is tonight.","zh-TW":"頒獎典禮今晚舉行。"}]', '{"verb":"award"}', NULL, 2, 271, NULL),
