(273, 'B2B', '/ˌbiː tə ˈbiː/', 'adjective', '{"zh-TW":["企業對企業的；B2B"],"en":["business to business; transactions between companies"]}', NULL, 'B2B sales / B2B marketing / B2B e-commerce / B2B platform', '[{"en":"The company shifted its focus from B2C to B2B customers.","zh-TW":"公司將重心從消費者市場轉向企業客戶。"},{"en":"B2B sales cycles are typically longer than consumer sales.","zh-TW":"B2B銷售週期通常比消費者銷售更長。"}]', '{"full form":"business to business"}', NULL, 1, 273, NULL),
(274, 'B2C', '/ˌbiː tə ˈsiː/', 'adjective', '{"zh-TW":["企業對消費者的；B2C"],"en":["business to consumer; transactions between a company and individual consumers"]}', NULL, 'B2C marketing / B2C platform / B2C e-commerce', '[{"en":"The new product line targets B2C customers through retail channels.","zh-TW":"新產品線通過零售渠道針對消費者客戶。"},{"en":"B2C brands invest heavily in social media advertising.","zh-TW":"B2C品牌在社群媒體廣告上投入大量資金。"}]', '{"full form":"business to consumer"}', NULL, 1, 274, NULL),
(275, 'baby', '/ˈbeɪbi/', 'noun', '{"zh-TW":["嬰兒；寶寶"],"en":["a very young child"]}', NULL, 'have a baby / baby products; baby shower / have a baby; baby shower / baby boom', '[{"en":"She is on maternity leave after having a baby.","zh-TW":"她生完孩子後在休產假。"},{"en":"Baby products are on the second floor.","zh-TW":"嬰兒用品在二樓。"},{"en":"The baby is sleeping.","zh-TW":"寶寶正在睡覺。"},{"en":"They''re having a baby next month.","zh-TW":"他們下個月要生寶寶了。"},{"en":"The baby is sleeping.","zh-TW":"寶寶在睡覺。"},{"en":"She''s expecting a baby in June.","zh-TW":"她預計六月生寶寶。"}]', '{"noun":"baby","adjective":"babyish"}', NULL, 1, 275, NULL),
(276, 'back', '/bæk/', 'noun', '{"zh-TW":["背部；後面","背部；後面；回去；支持"],"en":["the rear part of the body or thing","the rear part; to a previous position; to support"]}', NULL, 'go back / back and forth; go back / back up / at the back of', '[{"en":"My back hurts.","zh-TW":"我的背很痛。"},{"en":"I''ll be back in an hour.","zh-TW":"我一小時後回來。"},{"en":"He sat at the back of the room.","zh-TW":"他坐在房間後面。"},{"en":"I''ll be back in five minutes.","zh-TW":"我五分鐘後回來。"}]', '{"noun":"background, backup","adjective":"backward"}', NULL, 1, 276, NULL),
(277, 'background', '/ˈbækˌɡraʊnd/', 'noun', '{"zh-TW":["背景；背景資料"],"en":["a person''s history, education, or experience"]}', NULL, 'professional background / background check', '[{"en":"Her background in finance made her ideal for the role.","zh-TW":"她的金融背景使她非常適合這個職位。"},{"en":"A background check is required before the job offer is confirmed.","zh-TW":"在確認錄用前需要進行背景調查。"}]', NULL, NULL, 4, 277, 512),
