(280, 'backup', '/ˈbækʌp/', 'noun', '{"zh-TW":["備份"],"en":["a copy of data stored separately in case of loss"]}', NULL, 'create a backup / data backup', '[{"en":"Always create a backup of important files.","zh-TW":"務必對重要文件進行備份。"},{"en":"The system backup is scheduled to run at midnight.","zh-TW":"系統備份安排在午夜執行。"}]', '{"verb":"back up","adjective":"backed up"}', NULL, 2, 280, NULL),
(281, 'bad', '/bæd/', 'adjective', '{"zh-TW":["壞的；糟糕的","壞的；糟糕的；嚴重的"],"en":["of poor quality; unpleasant","of poor quality; unpleasant; serious"]}', NULL, 'not bad / go bad; go bad (變壞) / not bad (還不錯)', '[{"en":"The weather is really bad today.","zh-TW":"今天天氣真的很糟。"},{"en":"The milk has gone bad.","zh-TW":"牛奶壞了。"},{"en":"The weather was really bad yesterday.","zh-TW":"昨天天氣真的很糟。"},{"en":"I feel bad about what happened.","zh-TW":"我對發生的事感到抱歉。"}]', '{"adverb":"badly","noun":"badness"}', NULL, 1, 281, NULL),
(282, 'bag', '/bæɡ/', 'noun', '{"zh-TW":["袋子；包","袋子；手提包"],"en":["a container made of flexible material","a container made of paper, plastic, cloth, or leather"]}', NULL, 'shopping bag / bag of tricks; shopping bag / handbag / luggage bag', '[{"en":"She put the books in her bag.","zh-TW":"她把書放進了包裡。"},{"en":"Can I have a plastic bag?","zh-TW":"可以給我一個塑膠袋嗎？"},{"en":"She put the groceries in a bag.","zh-TW":"她把雜貨放進袋子裡。"},{"en":"Don''t forget your bag.","zh-TW":"別忘了你的包。"}]', NULL, NULL, 1, 282, NULL),
(283, 'baggage', '/ˈbægɪdʒ/', 'noun', '{"zh-TW":["行李"],"en":["bags and suitcases used when traveling"]}', NULL, 'carry-on baggage / excess baggage', '[{"en":"Passengers are allowed one piece of carry-on baggage.","zh-TW":"乘客可攜帶一件手提行李。"},{"en":"The airline charges a fee for excess baggage.","zh-TW":"航空公司對超重行李收費。"}]', '{"verb":"pack","adjective":"excess"}', NULL, 3, 283, NULL),
(284, 'bail', '/beɪl/', 'noun', '{"zh-TW":["保釋金"],"en":["money paid to release someone from jail before trial"]}', NULL, 'post bail / bail out', '[{"en":"The judge set bail at $50,000.","zh-TW":"法官將保釋金定為五萬美元。"},{"en":"His family posted bail.","zh-TW":"他的家人交了保釋金。"}]', NULL, NULL, 1, 284, NULL),
(285, 'balance', '/ˈbæləns/', 'noun', '{"zh-TW":["平衡；餘額"],"en":["an even distribution of weight","the amount of money remaining in an account"]}', '{"root":{"text":"bi","meaning":"two (二)"},"suffix":{"text":"-lance","meaning":"plate (盤)"},"logic":"兩個盤子的均衡，即「平衡」。"}', 'balance sheet / maintain balance / account balance', '[{"en":"Please check your account balance before making a transfer.","zh-TW":"轉帳前請確認帳戶餘額。"},{"en":"We must maintain a balance between cost and quality.","zh-TW":"我們必須在成本和品質之間保持平衡。"}]', '{"adjective":"balanced"}', NULL, 3, 285, 277),
