(288, 'ballet', '/bæˈleɪ/', 'noun', '{"zh-TW":["芭蕾舞"],"en":["a form of artistic dancing"]}', NULL, 'ballet dancer / ballet class', '[{"en":"She has studied ballet since age five.","zh-TW":"她從五歲開始學芭蕾。"},{"en":"We saw a beautiful ballet performance.","zh-TW":"我們看了一場美麗的芭蕾表演。"}]', NULL, NULL, 2, 288, NULL),
(289, 'ballot', '/ˈbælət/', 'noun', '{"zh-TW":["選票；投票"],"en":["a piece of paper used to vote"]}', NULL, 'secret ballot / ballot box', '[{"en":"Voters cast their ballots.","zh-TW":"選民投下了他們的選票。"},{"en":"The election was decided by ballot.","zh-TW":"選舉以投票方式決定。"}]', NULL, NULL, 2, 289, NULL),
(290, 'ban', '/bæn/', 'verb', '{"zh-TW":["禁止；禁令"],"en":["to officially prohibit something"]}', '{"root":{"text":"ban","meaning":"proclaim/forbid (宣告/禁止)"},"logic":"宣告禁止，即「禁止」。"}', 'ban on / impose a ban', '[{"en":"The city imposed a ban on single-use plastics.","zh-TW":"該市對一次性塑膠實施禁令。"},{"en":"Smoking is banned in all public buildings.","zh-TW":"所有公共建築內禁止吸菸。"}]', NULL, NULL, 1, 290, NULL),
(291, 'band', '/bænd/', 'noun', '{"zh-TW":["樂隊；帶子"],"en":["a group of musicians"]}', NULL, 'rock band / rubber band', '[{"en":"He plays guitar in a band.","zh-TW":"他在樂隊裡彈吉他。"},{"en":"The band performed live on stage.","zh-TW":"樂隊在舞台上現場演出。"}]', NULL, NULL, 1, 291, NULL),
(292, 'bandwidth', '/ˈbændwɪdθ/', 'noun', '{"zh-TW":["頻寬"],"en":["the amount of data that can be transmitted"]}', NULL, 'high bandwidth / bandwidth limit', '[{"en":"We need more bandwidth for video calls.","zh-TW":"我們需要更多頻寬進行視訊通話。"},{"en":"The server has limited bandwidth.","zh-TW":"伺服器頻寬有限。"}]', NULL, NULL, 3, 292, 752),
(293, 'bank', '/bæŋk/', 'noun', '{"zh-TW":["【主要意義-名詞】銀行；河岸","【次要意義-動詞】依靠；指望（bank on）","【次要意義-動詞】（飛機/車）傾斜轉彎","【次要意義-名詞】一排；一組（電腦/設備）"],"en":["[primary - noun] a financial institution; the land beside a river","[secondary - verb] to rely or depend on someone or something","[secondary - verb] to tilt to one side when turning","[secondary - noun] a row or series of similar objects"]}', NULL, 'bank on / bank holiday / bank of screens / river bank', '[{"en":"We cannot bank on government subsidies to cover the shortfall.","zh-TW":"我們不能指望政府補貼來彌補缺口。"},{"en":"The control room features a bank of monitoring screens.","zh-TW":"控制室配備了一排監控螢幕。"},{"en":"The branch manager banked on strong customer loyalty to boost sales.","zh-TW":"分行經理指望強烈的客戶忠誠度來提升銷售額。"}]', '{"noun":"banking, banker"}', 'bank on = 「依靠/指望」是 TOEIC 商業文章常見片語，a bank of（一排……）描述設備群組，這些次要意義完全不同於「銀行」，是常見陷阱。', 1, 293, NULL),
(294, 'bankrupt', '/ˈbæŋkrʌpt/', 'adjective', '{"zh-TW":["破產的"],"en":["unable to pay debts"]}', NULL, 'go bankrupt / declare bankrupt', '[{"en":"The company went bankrupt.","zh-TW":"公司破產了。"},{"en":"He was declared bankrupt by the court.","zh-TW":"他被法院宣告破產。"}]', '{"noun":"bankruptcy"}', NULL, 3, 294, NULL),
(295, 'bankruptcy', '/ˈbæŋkrʌptsi/', 'noun', '{"zh-TW":["破產"],"en":["a legal process for individuals or companies unable to repay debts"]}', NULL, 'declare bankruptcy / file for bankruptcy / bankruptcy protection', '[{"en":"The retail chain declared bankruptcy after the pandemic.","zh-TW":"這家零售連鎖店在疫情後宣布破產。"},{"en":"Bankruptcy protection gave the company time to restructure.","zh-TW":"破產保護給了公司重組的時間。"}]', '{"adjective":"bankrupt","verb":"bankrupt"}', NULL, 4, 295, NULL),
(296, 'banquet', '/ˈbæŋkwɪt/', 'noun', '{"zh-TW":["宴會；盛宴"],"en":["an elaborate meal for many people"]}', NULL, 'banquet hall / corporate banquet', '[{"en":"The hotel''s banquet hall can accommodate 500 guests.","zh-TW":"飯店的宴會廳可容納500位賓客。"},{"en":"They hosted a banquet to celebrate the company''s anniversary.","zh-TW":"他們舉辦了宴會慶祝公司周年紀念。"}]', '{"verb":"banquet"}', NULL, 3, 296, NULL),
(297, 'bar', '/bɑːr/', 'noun', '{"zh-TW":["酒吧；條；障礙"],"en":["a place serving drinks; a long narrow piece"]}', NULL, 'behind bars / bar chart', '[{"en":"Let''s meet at the bar.","zh-TW":"我們在酒吧見面吧。"},{"en":"He was put behind bars.","zh-TW":"他被關進了監獄。"}]', '{"verb":"bar","noun2":"bartender"}', NULL, 1, 297, NULL),
(298, 'barely', '/ˈbeərli/', 'adverb', '{"zh-TW":["勉強；幾乎不"],"en":["only just; almost not"]}', '{"root":{"text":"bare","meaning":"bare/merely (僅僅)"},"suffix":{"text":"-ly","meaning":"in manner of (以…方式)"},"logic":"僅僅的方式，即「勉強」。"}', 'barely visible / barely enough / can barely', '[{"en":"She barely passed the exam.","zh-TW":"她勉強通過了考試。"},{"en":"I can barely hear you.","zh-TW":"我幾乎聽不到你說話。"}]', NULL, NULL, 2, 298, NULL),
(299, 'bargain', '/ˈbɑːrɡɪn/', 'noun', '{"zh-TW":["便宜貨；協議","討價還價","便宜貨；交易"],"en":["something bought cheaply","an agreement between parties","to negotiate terms of a deal"]}', '{"root":{"text":"bargain","meaning":"trade/negotiate (交易)"},"logic":"通過交易談判達成的，即「便宜貨、協議」。"}', 'bargain price / collective bargaining; a real bargain / bargain hunter', '[{"en":"The property was a real bargain at that price.","zh-TW":"以那個價格買下這處房產真是便宜。"},{"en":"The union engaged in collective bargaining.","zh-TW":"工會進行了集體談判。"},{"en":"This coat was a real bargain at half price.","zh-TW":"這件外套半價，真是便宜貨。"},{"en":"They bargained with the vendor for a lower price.","zh-TW":"他們跟攤販討價還價。"}]', '{"verb":"bargain"}', NULL, 3, 299, NULL);